    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Biomedical Research Landscape 2024–2026</title>
    <style>
        * {{
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }}

        body {{
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            line-height: 1.6;
            color: #2D3142;
            background: #f8f9fa;
        }}

        .container {{
            max-width: 1200px;
            margin: 0 auto;
            padding: 20px;
        }}

        header {{
            background: linear-gradient(135deg, #1E3A5F 0%, #2E86AB 100%);
            color: white;
            padding: 60px 40px;
