#!/usr/bin/env python3
"""
Biomedical Research Landscape 2024–2026: Trend Analysis Report Generator
"""

import pandas as pd
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
import numpy as np
import base64
from io import BytesIO
from datetime import datetime
import json
import os

# Set style for professional charts
plt.style.use('seaborn-v0_8-whitegrid')
plt.rcParams['figure.facecolor'] = 'white'
plt.rcParams['axes.facecolor'] = 'white'
plt.rcParams['font.family'] = 'DejaVu Sans'

# Color palette - professional blue/green theme
COLORS = {
    'primary': '#1E3A5F',      # Deep navy
    'secondary': '#2E86AB',     # Steel blue
    'accent': '#48A9A6',        # Teal
    'warning': '#E07A5F',       # Coral
    'success': '#81B29A',       # Sage
    'text': '#2D3142',         # Dark slate
    'light': '#F4F4F8',        # Light gray
    'grid': '#E0E0E0'
}

def load_data():
    """Load and prepare the dataset"""
    df = pd.read_csv('/app/benchmark/data.csv')
    print(f"Loaded {len(df)} records")
    return df

def compute_kpis(df):
    """Compute all required KPIs"""
    kpis = {}

    # Total Publications
    kpis['total_publications'] = len(df)
    kpis['by_year'] = df.groupby('pub_year').size().to_dict()

    # Open Access Rate
    kpis['oa_rate'] = df['open_access'].mean() * 100
    kpis['oa_by_year'] = df.groupby('pub_year')['open_access'].mean() * 100

    # Median Authors per Publication
    kpis['median_authors'] = df['authors_count'].median()
    kpis['authors_by_year'] = df.groupby('pub_year')['authors_count'].median()

    # Top 10 Countries Share
    top10_count = df['country'].value_counts().head(10).sum()
    kpis['top10_countries_share'] = (top10_count / len(df)) * 100
    kpis['top10_countries'] = df['country'].value_counts().head(10)

    # Emerging Topic Growth Rate (month-over-month for major topics)
    # Focus on topics with enough data for meaningful analysis
    return kpis

def get_temporal_trends(df):
    """Analyze temporal publication trends"""
    # Monthly publication counts by year
    monthly = df.groupby(['pub_year', 'pub_month_num']).size().reset_index(name='count')

    # Year totals
    yearly = df['pub_year'].value_counts().sort_index()

    # Known months data (exclude 0 which is Unknown)
    known_months = df[df['pub_month_num'] > 0]
    monthly_known = known_months.groupby(['pub_year', 'pub_month_num']).size().reset_index(name='count')

    return {
        'yearly': yearly,
        'monthly': monthly_known,
        'unknown_months_pct': (df['pub_month_num'] == 0).sum() / len(df) * 100
    }

def get_geographic_analysis(df):
    """Analyze geographic distribution"""
    # Top countries by year
    geo_by_year = df.groupby(['pub_year', 'country']).size().reset_index(name='count')
    geo_pivot = geo_by_year.pivot(index='country', columns='pub_year', values='count').fillna(0)

    # Top 15 countries overall
    top_countries = df['country'].value_counts().head(15)

    # Country share over time
    total_by_year = df.groupby('pub_year').size()
    top5 = top_countries.head(5).index.tolist()

    return {
        'top_countries': top_countries,
        'geo_pivot': geo_pivot,
        'top5': top5,
        'total_by_year': total_by_year
    }

def get_topic_analysis(df):
    """Analyze research topics and MeSH keywords"""
    # Major topics
    major_topics = df['major_topic'].value_counts().head(20)

    # Topics by year
    topics_by_year = df.groupby(['pub_year', 'major_topic']).size().reset_index(name='count')
    topics_pivot = topics_by_year.pivot(index='major_topic', columns='pub_year', values='count').fillna(0)

    # Emerging topics (highest growth from 2024 to 2025)
    topics_pivot['growth'] = topics_pivot.get(2025, 0) / (topics_pivot.get(2024, 1) + 0.1)
    emerging = topics_pivot.sort_values('growth', ascending=False).head(10)

    # Month-over-month growth for top topics
    # Calculate MoM growth for 2024 (most complete year)
    df_2024 = df[df['pub_year'] == 2024]
    monthly_topics = df_2024[df_2024['pub_month_num'] > 0].groupby(
        ['pub_month_num', 'major_topic']
    ).size().unstack(fill_value=0)

    return {
        'major_topics': major_topics,
        'topics_pivot': topics_pivot,
        'emerging': emerging,
        'monthly_topics': monthly_topics
    }

def get_open_access_analysis(df):
    """Analyze open access patterns"""
    # OA by year
    oa_by_year = df.groupby('pub_year')['open_access'].agg(['sum', 'count', 'mean'])
    oa_by_year['rate'] = oa_by_year['mean'] * 100

    # OA by country (top 10 countries)
    oa_by_country = df.groupby('country')['open_access'].mean() * 100

    # Journal analysis
    top_journals = df['journal'].value_counts().head(15)

    return {
        'oa_by_year': oa_by_year,
        'oa_by_country': oa_by_country,
        'top_journals': top_journals
    }

def get_research_type_analysis(df):
    """Analyze research types and collaboration"""
    # Research types - handle multi-value field
    all_types = []
    for rt in df['research_type'].dropna():
        types = [t.strip() for t in str(rt).split(';')]
        all_types.extend(types)

    type_counts = pd.Series(all_types).value_counts()

    # Author count distribution
    author_bins = [0, 1, 3, 5, 10, 20, 100]
    author_labels = ['1', '2-3', '4-5', '6-10', '11-20', '20+']
    df['author_group'] = pd.cut(df['authors_count'], bins=author_bins, labels=author_labels, right=True)

    author_dist = df['author_group'].value_counts()

    # Authors by country
    authors_by_country = df.groupby('country')['authors_count'].median()

    return {
        'type_counts': type_counts,
        'author_dist': author_dist,
        'authors_by_country': authors_by_country
    }

def create_chart(chart_func, figsize=(10, 6)):
    """Generate chart as base64 encoded image"""
    fig, ax = plt.subplots(figsize=figsize)
    chart_func(fig, ax)
    buf = BytesIO()
    plt.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    img_base64 = base64.b64encode(buf.getvalue()).decode()
    plt.close()
    return img_base64

def chart_yearly_trends(temporal):
    """Publication volume over time"""
    def _chart(fig, ax):
        yearly = temporal['yearly']
        bars = ax.bar(yearly.index.astype(str), yearly.values, color=COLORS['secondary'], edgecolor='white')
        ax.set_xlabel('Year', fontsize=12, color=COLORS['text'])
        ax.set_ylabel('Number of Publications', fontsize=12, color=COLORS['text'])
        ax.set_title('Publication Volume by Year', fontsize=14, fontweight='bold', color=COLORS['primary'])

        # Add value labels on bars
        for bar in bars:
            height = bar.get_height()
            ax.annotate(f'{int(height):,}',
                       xy=(bar.get_x() + bar.get_width()/2, height),
                       ha='center', va='bottom', fontsize=11, fontweight='bold', color=COLORS['primary'])

        ax.spines['top'].set_visible(False)
        ax.spines['right'].set_visible(False)
        ax.set_facecolor('white')
    return _chart

def chart_monthly_trends(temporal):
    """Monthly publication trends (2024)"""
    def _chart(fig, ax):
        monthly = temporal['monthly']
        if 2024 in monthly['pub_year'].values:
            m2024 = monthly[monthly['pub_year'] == 2024].sort_values('pub_month_num')
            ax.plot(m2024['pub_month_num'], m2024['count'], marker='o', linewidth=2,
                   color=COLORS['secondary'], markersize=8)

            # Month labels
            month_names = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                         'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
            ax.set_xticks(range(1, 13))
            ax.set_xticklabels(month_names, rotation=45, ha='right')
            ax.set_xlabel('Month (2024)', fontsize=12, color=COLORS['text'])
            ax.set_ylabel('Publications', fontsize=12, color=COLORS['text'])
            ax.set_title('Monthly Publication Trend (2024)', fontsize=14, fontweight='bold', color=COLORS['primary'])
            ax.spines['top'].set_visible(False)
            ax.spines['right'].set_visible(False)
    return _chart

def chart_geographic(geo):
    """Top countries bar chart"""
    def _chart(fig, ax):
        top15 = geo['top_countries'].head(15)
        colors = [COLORS['secondary'] if i < 5 else COLORS['accent'] for i in range(len(top15))]
        bars = ax.barh(range(len(top15)), top15.values, color=colors)
        ax.set_yticks(range(len(top15)))
        ax.set_yticklabels(top15.index)
        ax.invert_yaxis()
        ax.set_xlabel('Number of Publications', fontsize=12, color=COLORS['text'])
        ax.set_title('Top 15 Countries by Publication Count', fontsize=14, fontweight='bold', color=COLORS['primary'])
        ax.spines['top'].set_visible(False)
        ax.spines['right'].set_visible(False)

        # Add value labels
        for i, (bar, val) in enumerate(zip(bars, top15.values)):
            ax.text(val + 5, i, f'{int(val):,}', va='center', fontsize=9, color=COLORS['text'])
    return _chart

def chart_oa_trend(oa_data):
    """Open access rate over time"""
    def _chart(fig, ax):
        oa_by_year = oa_data['oa_by_year']
        years = oa_by_year.index.astype(str)
        rates = oa_by_year['rate'].values
        bars = ax.bar(years, rates, color=COLORS['success'], edgecolor='white')
        ax.set_xlabel('Year', fontsize=12, color=COLORS['text'])
        ax.set_ylabel('Open Access Rate (%)', fontsize=12, color=COLORS['text'])
        ax.set_title('Open Access Publication Rate by Year', fontsize=14, fontweight='bold', color=COLORS['primary'])
        ax.set_ylim(0, 100)

        for bar in bars:
            height = bar.get_height()
            ax.annotate(f'{height:.1f}%',
                       xy=(bar.get_x() + bar.get_width()/2, height),
                       ha='center', va='bottom', fontsize=11, fontweight='bold', color=COLORS['primary'])

        ax.spines['top'].set_visible(False)
        ax.spines['right'].set_visible(False)
    return _chart

def chart_research_types(type_data):
    """Research type distribution"""
    def _chart(fig, ax):
        types = type_data['type_counts'].head(10)
        colors = plt.cm.Set3(np.linspace(0, 1, len(types)))
        wedges, texts, autotexts = ax.pie(types.values, labels=types.index, autopct='%1.1f%%',
                                           colors=colors, pctdistance=0.75)
        ax.set_title('Research Type Distribution', fontsize=14, fontweight='bold', color=COLORS['primary'])
        for text in texts:
            text.set_fontsize(9)
        for autotext in autotexts:
            autotext.set_fontsize(8)
    return _chart

def chart_authors_distribution(type_data):
    """Author count distribution"""
    def _chart(fig, ax):
        author_dist = type_data['author_dist'].reindex(['1', '2-3', '4-5', '6-10', '11-20', '20+'])
        colors = [COLORS['secondary'], COLORS['secondary'], COLORS['accent'], COLORS['accent'], COLORS['warning'], COLORS['warning']]
