        ax.set_xlabel('Number of Authors', fontsize=12, color=COLORS['text'])
        ax.set_ylabel('Number of Publications', fontsize=12, color=COLORS['text'])
        ax.set_title('Author Count Distribution', fontsize=14, fontweight='bold', color=COLORS['primary'])


        for bar in bars:
            height = bar.get_height()
            if height > 0:
                ax.annotate(f'{int(height):,}',
                           xy=(bar.get_x() + bar.get_width()/2, height),
                           ha='center', va='bottom', fontsize=9, color=COLORS['primary'])

        ax.spines['top'].set_visible(False)
        ax.spines['right'].set_visible(False)
    return _chart

def chart_major_topics(topic_data):
    """Top major topics"""
    def _chart(fig, ax):
        topics = topic_data['major_topics'].head(15)
        colors = [COLORS['primary'] if i < 5 else COLORS['secondary'] for i in range(len(topics))]
        bars = ax.barh(range(len(topics)), topics.values, color=colors)
        ax.set_yticks(range(len(topics)))
        ax.set_yticklabels([t[:30] + '...' if len(t) > 30 else t for t in topics.index])
        ax.invert_yaxis()
        ax.set_xlabel('Number of Publications', fontsize=12, color=COLORS['text'])
        ax.set_title('Top 15 Major Topics (MeSH)', fontsize=14, fontweight='bold', color=COLORS['primary'])
        ax.spines['top'].set_visible(False)
        ax.spines['right'].set_visible(False)
    return _chart

def chart_top_journals(oa_data):
    """Top journals by volume"""
    def _chart(fig, ax):
        journals = oa_data['top_journals'].head(12)
        colors = [COLORS['secondary'] if i < 5 else COLORS['accent'] for i in range(len(journals))]
        bars = ax.barh(range(len(journals)), journals.values, color=colors)
        ax.set_yticks(range(len(journals)))
        ax.set_yticklabels([j[:35] + '...' if len(j) > 35 else j for j in journals.index])
        ax.invert_yaxis()
        ax.set_xlabel('Number of Publications', fontsize=12, color=COLORS['text'])
