        'authors_dist': create_chart(chart_authors_distribution(type_data)),
        'major_topics': create_chart(chart_major_topics(topics), figsize=(12, 7)),
        'top_journals': create_chart(chart_top_journals(oa_data), figsize=(12, 7))
    }

    # Calculate MoM growth for emerging topics (using 2024 monthly data)
    monthly_topics = topics['monthly_topics']
